                hashes.append(photo["sha256"])
            if len(set(hashes))!=3:raise HTTPException(400,"三张照片不能重复")
            jid=enqueue(s,self.folder(s["session_id"]))
            s["jobs"][str(revision)]=jid;s["status"]="submitted";s["stream_id"]=None
